import heapq

def solve() -> None:
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    N = next(it)
    M = next(it)
    X = next(it)

    # adjacency for normal moves (mode 0) and reversed moves (mode 1)
    adj = [[] for _ in range(N + 1)]
    radj = [[] for _ in range(N + 1)]

    for _ in range(M):
        u = next(it)
        v = next(it)
        adj[u].append(v)      # normal direction u -> v
        radj[v].append(u)      # reversed direction v -> u uses original u -> v

    INF = 10 ** 30
    dist0 = [INF] * (N + 1)
    dist1 = [INF] * (N + 1)

    dist0[1] = 0
    pq = [(0, 1, 0)]          # (cost, vertex, mode)

    while pq:
        d, v, p = heapq.heappop(pq)
        if p == 0:
            if d != dist0[v]:
                continue
        else:
            if d != dist1[v]:
                continue

        # 1) move along an edge (cost 1)
        if p == 0:
            nd = d + 1
            for w in adj[v]:
                if nd < dist0[w]:
                    dist0[w] = nd
                    heapq.heappush(pq, (nd, w, 0))
        else:
            nd = d + 1
            for w in radj[v]:
                if nd < dist1[w]:
                    dist1[w] = nd
                    heapq.heappush(pq, (nd, w, 1))

        # 2) reverse the whole graph (cost X)
        np = 1 - p
        nd = d + X
        if np == 0:
            if nd < dist0[v]:
                dist0[v] = nd
                heapq.heappush(pq, (nd, v, 0))
        else:
            if nd < dist1[v]:
                dist1[v] = nd
                heapq.heappush(pq, (nd, v, 1))

    answer = min(dist0[N], dist1[N])
    print(answer)


if __name__ == "__main__":
    solve()

