class Node:
    __slots__ = ('val', 'prio', 'l', 'r', 'size')
    def __init__(self, val):
        self.val = val          # element to output
        self.prio = random.getrandbits(64)
        self.l = None
        self.r = None
        self.size = 1

def upd(t):
    if t:
        t.size = 1
        if t.l:
            t.size += t.l.size
        if t.r:
            t.size += t.r.size

def split(t, k):
    """Return (L, R) where L has first k nodes, R the rest."""
    if not t:
        return (None, None)
    ls = t.l.size if t.l else 0
    if k <= ls:
        L, mid = split(t.l, k)
        t.l = mid
        upd(t)
        return (L, t)
    else:
        mid, R = split(t.r, k - ls - 1)
        t.r = mid
        upd(t)
        return (t, R)

def merge(a, b):
    if not a or not b:
        return a or b
    if a.prio > b.prio:
        a.r = merge(a.r, b)
        upd(a)
        return a
    else:
        b.l = merge(a, b.l)
        upd(b)
        return b

def inorder_collect(t, out):
    if not t:
        return
    inorder_collect(t.l, out)
    out.append(t.val)
    inorder_collect(t.r, out)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    P = [int(next(it)) for _ in range(N)]

