        # Insert i at position p (1‑based) → zero‑based index p-1
        L, R = split(root, p - 1)
        node = Node(i)
        root = merge(merge(L, node), R)

    res = []
    inorder_collect(root, res)
    print(' '.join(map(str, res)))

